strategy_source:character:
function (ctx, params) 
{
    targets <- ctx$hold()
    if (identical(substr(ctx$ts_utc, 1L, 10L), "2020-01-02") && identical(ctx$state$observed_cash, 1000)) {
        targets["AAA"] <- params$qty
    }
    list(targets = targets, state_update = list(observed_cash = ctx$cash))
}

